 private final TextView disclosure,status,reader;private final CheckBox ack;private final Spinner history;private final List<String>historyIds=new ArrayList<>();
 public WatchlistReconciliationScreen(Context context,WatchlistReconciliationStore s,InputReader r,Confirmer c){super(context);store=s;inputReader=r;confirmer=c;setOrientation(VERTICAL);setPadding(dp(6),dp(4),dp(6),dp(4));setTag("watchlistReconciliationScreen");disclosure=label("主自选变化后的本地关联协调 · 完整旧配置入历史 · 不更新来源云端",12);addView(disclosure);LinearLayout bar=row(this);button(bar,"重读","reconciliationReload",this::reload);button(bar,"预览","reconciliationPreview",this::previewChanges);button(bar,"明确确认","reconciliationConfirm",this::confirmChanges);button(bar,"取消","reconciliationCancel",this::cancelChanges);ack=new CheckBox(context);ack.setText("已核对并接受移除关联和完整旧配置入历史保留");ack.setTextSize(12);ack.setTag("reconciliationAck");addView(ack);status=label("",12);status.setMaxLines(3);status.setTag("reconciliationStatus");addView(status);ScrollView viewport=new ScrollView(context);viewport.setTag("reconciliationViewport");reader=label("",13);reader.setTextIsSelectable(true);reader.setTag("reconciliationReader");viewport.addView(reader);addView(viewport,new LayoutParams(-1,0,1));LinearLayout navigation=row(this);button(navigation,"上一段","reconciliationPrevious",()->{offset=Math.max(0,offset-24000);paintReader();});button(navigation,"下一段","reconciliationNext",()->{if(offset+24000<fullText.length())offset+=24000;paintReader();});history=new Spinner(context);history.setTag("reconciliationHistory");navigation.addView(history,new LayoutParams(0,-1,2));button(navigation,"读历史","reconciliationOpenHistory",()->{int at=history.getSelectedItemPosition();need(at>0&&at<historyIds.size(),"请选择明确历史版本");openHistory(historyIds.get(at));});setDarkTheme(false);attempt(this::reload);}
