 private void listHistory()throws Exception{historyIds.clear();historyIds.add("");List<String>labels=new ArrayList<>();labels.add("请选择协调历史");JSONArray rows=store.historyList();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);historyIds.add(text(r,"id"));labels.add(text(r,"confirmedAt")+" · "+text(r,"beforeRevision")+" → "+text(r,"afterRevision"));}history.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels){private View paint(View v){((TextView)v).setTextColor(dark?Color.rgb(220,229,240):Color.rgb(36,52,73));v.setBackgroundColor(dark?Color.rgb(23,34,50):Color.rgb(244,247,251));return v;}public View getView(int n,View old,ViewGroup p){return paint(super.getView(n,old,p));}public View getDropDownView(int n,View old,ViewGroup p){return paint(super.getDropDownView(n,old,p));}});}
 public void reload()throws Exception{need(store!=null&&inputReader!=null,"未接当前本机配置与完整主自选输入");JSONObject result=store.current(inputReader.read());packet=new JSONObject();uncertain=false;historyId="";ack.setChecked(false);offset=0;fullText=result.toString(2);paintReader();listHistory();status.setText(result.getString("state").equals("ready")?"当前范围已协调；重读未写配置。":"当前范围待协调；原关系完整保留，请先预览。");}
