 public void confirmChanges()throws Exception{need(!uncertain&&packet.length()>0&&ack.isChecked()&&inputReader!=null,"先预览并明确接受完整旧配置入历史");need(equal(store.preview(inputReader.read()),packet),"确认前配置或当前证券已变，请重新预览");if(packet.getBoolean("noChange")){cancelChanges();status.setText("没有范围变化；未调用确认或迁移。");return;}need(confirmer!=null,"宿主未接主线程 / 协调锁下的确认回调");uncertain=true;JSONObject result=confirmer.confirm(copy(packet),true);need(text(result,"schema").equals("watchlist-reconciliation-result/v1")&&text(result,"state").equals("committed")&&equal(result.get("previewHash"),packet.get("summaryHash")),"协调回执未确认请求摘要");JSONObject record=store.history(text(result,"historyId"));need(equal(record.get("preview"),packet)&&equal(record.get("afterConfig"),result.get("config")),"协调回执与完整历史不一致");JSONObject snapshot=validate(result.getJSONObject("snapshot"));need(equal(WatchlistWorkspaceStore.config(snapshot),record.get("afterConfig"))&&equal(WatchlistReconciliationModel.scope(object("mainIds",snapshot.get("mainIds"),"instruments",snapshot.get("instruments"))),record.get("rosterScope")),"协调回执主自选身份未确认");uncertain=false;packet=new JSONObject();ack.setChecked(false);openHistory(text(result,"historyId"));listHistory();status.setText("本地关联协调已保存，完整旧配置和关系已入历史；主自选与行情未写。");}
 public void cancelChanges()throws Exception{need(!uncertain,"保存结果未确认，请明确重读配置与历史");packet=new JSONObject();ack.setChecked(false);historyId="";fullText="";offset=0;paintReader();status.setText("已取消预览；未调用确认、未迁移、未写配置。");}
