 public void restoreViewState(JSONObject s)throws Exception{need(text(s,"schema").equals("watchlist-reconciliation-view/v1")&&s.opt("packet") instanceof JSONObject&&s.opt("uncertain") instanceof Boolean&&s.opt("readOffset") instanceof Number,"协调页面状态损坏");JSONObject pending=copy(s.getJSONObject("packet"));String id=text(s,"historyId");if(pending.length()>0)need(text(pending,"schema").equals("watchlist-reconciliation-preview/v1"),"协调预览状态格式无效");String body=pending.length()>0?WatchlistReconciliationModel.describe(pending)+pending.toString(2):!id.isEmpty()?"完整历史：含协调前全部配置和原成员顺序\n"+store.history(id).toString(2):"";packet=pending;uncertain=s.getBoolean("uncertain");historyId=id;offset=Math.max(0,s.getInt("readOffset"));fullText=body;ack.setChecked(false);paintReader();listHistory();status.setText("页面已恢复；需重新核对勾选，提交仍复核配置和当前身份。");}
